      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'black';
      ctx.beginPath();
      ctx.arc(canvas.width / 2, canvas.height / 2, 10, 0, 2 * Math.PI);
      ctx.fill();
      ctx.beginPath();
      ctx.arc(canvas.width / 2 + Math.sin(angle) * length, canvas.height / 2 - 10 * Math.cos(angle), 10, 0, 2 * Math.PI);
      ctx.fillStyle = 'red';
      ctx.fill();
    }

    function update() {
      if (release) {
        velocity += -angle * 0.1;
        angle += velocity;
        velocity *= damping;
        if (Math.abs(angle) < 0.1) {
