)

func handler(ctx context.Context) (interface{}, error) {
	// Create an EC2 session
	sess, err := session.NewSession(&aws.Config{Region: aws.String("your-region")}, nil)
	if err != nil {
		log.Println(err)
		return nil, err
	}
	ec2Svc := ec2.New(sess)

	// Get a list of EBS snapshots with the "backup_type" tag
	params := &ec2DescribeSnapshotsInput{
		Filters: []*ec2.Filter{
			{
				Name:  aws.String("tag:backup_type"),
				Values: []*string{aws.String("monthly"), aws.String("daily"), aws.String("weekly"), aws.String("yearly")},
			},
		},
	}
	snapshots, err := ec2Svc.DescribeSnapshots(context.TODO(), params)
	if err != nil {
		log.Println(err)
		return nil, err
	}

	// Process each snapshot
	for _, snap := range snapshots.Snapshots {
		backupType := *snap.Tags[0].Value
		switch backupType {
		case "monthly":
			// Keep the last 14 monthly snapshots
			if len(snapshots.Snapshots) > 14 {
				err = ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{SnapshotId: snap.SnapshotId})
				if err != nil {
					log.Println(err)
					return nil, err
				}
			}
		case "daily":
			// Keep the last 10 daily snapshots
			if len(snapshots.Snapshots) > 10 {
				err = ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{SnapshotId: snap.SnapshotId})
				if err != nil {
					log.Println(err)
					return nil, err
				}
			}
		case "weekly":
			// Keep the last 4 weekly snapshots
			if len(snapshots.Snapshots) > 4 {
				err = ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{SnapshotId: snap.SnapshotId})
				if err != nil {
					log.Println(err)
					return nil, err
				}
			}
		case "yearly":
			// Keep only 1 yearly snapshot
			if len(snapshots.Snapshots) > 1 {
				err = ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{SnapshotId: snap.SnapshotId})
				if err != nil {
					log.Println(err)
					return nil, err
				}
			}
		}
	}

	log.Println("Completed deleting EBS snapshots")
	return nil, nil
}

func main() {
	lambda.Start(handler)
}
