**router.js**
```javascript
const urls = [
  'https://api.example.com/page1',
  'https://api.example.com/page2',
  'https://api.example.com/page3',
  'https://api.example.com/page4',
  'https://api.example.com/page5',
  'https://api.example.com/page6',
  'https://api.example.com/page7',
  'https://api.example.com/page8',
  'https://api.example.com/page9',
  'https://api.example.com/page10'
];

let counter = 0;

fetch('/api/counter')
  .then(response => response.json())
  .then(data => {
    counter = data.counter;
  })
  .catch(error => console.error(error));

setInterval(() => {
  const url = urls[counter % urls.length];
  fetch(url)
    .then(response => response.text())
    .then(data => {
      document.getElementById('router-content').innerHTML = data;
    })
    .catch(error => console.error(error));

  counter++;
  flushToAsyncStorage();
}, 10000);

function flushToAsyncStorage() {
  fetch('/api/counter', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ counter: counter })
  })
    .catch(error => console.error(error));
}
```
