export default async function handler(req, res) {
  const { method } = req;

  switch (method) {
    case 'POST':
      // Login logic
      const loginResponse = await login(req.body);
      if (loginResponse) {
        const session = await updateSession(req, res, loginResponse);
        res.json(session);
      } else {
        res.status(401).json({ error: 'Invalid credentials' });
      }
      break;

    default:
      res.setHeader('Allow', ['POST']);
      res.status(405).send({ error: `Method ${method} Not Allowed` });
  }
}
```
With:
