import { NextApiRequest, NextApiResponse } from 'next';
import { jwtVerify } from 'next-auth';

export default async function verifyJwtToken(req: NextApiRequest, res: NextApiResponse) {
  const token = req.headers.authorization;

  if (!token) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  try {
    const decoded = await jwtVerify(token, process.env.NEXT_AUTH_JWT_SECRET_KEY);
    req.user = decoded;
  } catch (error) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}
```
