                    client.EnableSsl = true; // replace with your SMTP SSL setting
                    client.Credentials = new NetworkCredential(fromAddress, currentAccount.Password);

                    client.Send(mail);
                }
            }
        }
    }

    private EmailAccount GetNextEmailAccount()
    {
        int index = EmailAccounts.Find(e => e.Index == 0).Index;
