```csharp
using System;

namespace ChatSystem
{
    // The mediator, which will manage the chat
    public class ChatMediator : IChatMediator
    {
        private readonly PrintWriter Receiver;
        private readonly PublishSubject<ChatMessage> Messages;

        public ChatMediator(PrintWriter receiver)
        {
            Receiver = receiver;
            Messages = new PublishSubject<ChatMessage>();
        }

        public void SendMessage(string message, User user)
        {
            ChatMessage chatMessage = new ChatMessage(user, message);
            Messages.OnNext(chatMessage);
        }
    }

    public interface IChatMediator
    {
        void SendMessage(string message, User user);
    }

    public class ChatMessage
    {
        public User User { get; set; }
        public string Message { get; set; }

        public ChatMessage(User user, string message)
        {
            User = user;
            Message = message;
        }
    }

    public class User
    {
        public string Name { get; set; }

        public User(string name)
        {
            Name = name;
        }
    }

    public class PrintWriter
    {
        public void Print(string message)
        {
            Console.WriteLine(message);
        }
    }

    // The clients, which will interact with the mediator
    public class UserA : IChatUser
    {
        private readonly ChatMediator mediator;
        private readonly string name;

        public UserA(ChatMediator mediator, string name)
        {
            this.mediator = mediator;
            this.name = name;
        }

        public void SendMessage(string message)
        {
            mediator.SendMessage(message, this);
        }
    }

    public interface IChatUser
    {
        void SendMessage(string message);
    }

    public class UserB : IChatUser
    {
        private readonly ChatMediator mediator;
        private readonly string name;

        public UserB(ChatMediator mediator, string name)
        {
            this.mediator = mediator;
            this.name = name;
        }

        public void SendMessage(string message)
        {
            mediator.SendMessage(message, this);
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            // Create the chat mediator
            ChatMediator mediator = new ChatMediator(new PrintWriter());

            // Create the users
            UserA userA = new UserA(mediator, "Alice");
            UserB userB = new UserB(mediator, "Bob");

            // Start the conversation
            userA.SendMessage("Hello, Bob!");
            userB.SendMessage("Hi, Alice!");
        }
    }
}

