Here is a C++ program that renames every file inside a given folder with a 3-digit number, sorted by file creation date:
```cpp
#include <iostream>
#include <filesystem>
#include <vector>
#include <algorithm>
#include <string>
#include <utility>

using namespace std;
namespace fs = std::filesystem;

int main() {
    // Ask the user for the folder path
    string folderPath;
    cout << "Enter the folder path: ";
    getline(cin, folderPath);

    // Get a list of all files in the folder, sorted by creation date
    vector<fs::path> filesInFolder;
    for (const auto& entry : fs::directory_iterator(folderPath)) {
        if (entry.is_regular_file()) {
            filesInFolder.push_back(entry.path());
        }
    }
    sort(filesInFolder.begin(), filesInFolder.end(), [](const fs::path& a, const fs::path& b) {
        return fs::last_write_time(a) < fs::last_write_time(b);
    });

    // Rename each file with a 3-digit number suffix
    int count = 0;
    for (const auto& file : filesInFolder) {
        count++;
        string newName = file.filename().string() + "_" + to_string(count);
        fs::rename(file, folderPath / fs::path(newName));
    }

    cout << "Files renamed successfully!" << endl;
    return 0;
}
