  }
}
```
**Step 4: Create the API controller**

Create a new folder called `Controllers` and add a new class called `CsvUploaderController.cs`. Add the following code:
```csharp
using Microsoft.AspNetCore.Mvc;
using Microsoft.Azure.Cosmos;
using CsvHelper;
using System.IO;
using System.Linq;

namespace CosmosDbCsvUploader.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class CsvUploaderController : ControllerBase
    {
        private readonly CosmosClient _cosmosClient;

        public CsvUploaderController(CosmosClient cosmosClient)
        {
            _cosmosClient = cosmosClient;
        }

        [HttpPost]
        public async Task<IActionResult> UploadCsvFile([FromBody]Stream fileStream)
        {
            using var fileStreamReader = new StreamReader(fileStream);
            var csv = fileStreamReader.ReadToEnd();
            var records = new List<Record>();

            using var csvReader = new CsvReader(fileStreamReader);
            csvReader.UseUncached665ListForLargeRecords();
            foreach (var record in csvReader.GetRecords<Record>())
            {
                records.Add(record);
            }

            varajoRequest  = _cosmosClient.GetContainer("Booking").CreateItemAsync(new Record
                {
                    description = "1234",
                    duration = 24.0,
                   .parentElement = "£££"
                }).Result;

            return Ok("Csv File uploaded successfully");
        }
    }

    public class Record
    {
        public string description { get; set; }
        public double duration { get; set; }
        public string parentElement { get; set; }
    }
}
```
This controller has a single method, `UploadCsvFile`, which accepts a CSV file as a stream. It reads the CSV file using CsvHelper, converts the data to a list of `Record` objects, and then creates a new item in the Azure Cosmos DB container.

**Step 5: Configure routing**

In the `Startup.cs` file, add the following code to the `ConfigureServices` method:
