contract MyNFTCollection {
    // Mapping of token IDs to owner addresses
    mapping (uint256 => address) public tokenOwner;

    // Mapping of token IDs to token metadata
    mapping (uint256 => string) public tokenMetaData;

    // Total supply of NFTs
    uint256 public totalSupply;

    // Event emitted when a new NFT is minted
    event NewNFT(uint256 indexed tokenID, address indexed owner);

    // Event emitted when an NFT is transferred
    event TransferNFT(uint256 indexed tokenID, address indexed from, address indexed to);

    // Mapping of token IDs to whether they are sold or not
    mapping (uint256 => bool) public isTokenSold;

    // Mapping of token IDs to the sale price of each NFT
    mapping (uint256 => uint256) public tokenSalePrice;

    // Mapping of token IDs to the buyer of each NFT
    mapping (uint256 => address) public tokenBuyer;

    // Constructor function that sets up the contract
    constructor() public {
        totalSupply = 1000; // set the total supply of NFTs to 1000
    }

    // Function to mint a new NFT
    function mintNFT(address newOwner, string memory metaData) public {
        require(totalSupply > 0, "Minting is not allowed");
        require(tokenOwner[totalSupply].address == address(0), "This token has already been minted");

        tokenOwner[totalSupply] = newOwner;
        tokenMetaData[totalSupply] = metaData;
        totalSupply -= 1;

        emit NewNFT(totalSupply, newOwner);
    }

    // Function to transfer an NFT
    function transferNFT(uint256 tokenID, address newOwner) public {
        require(tokenOwner[tokenID].address == msg.sender, "You are not the owner of this NFT");
        require(tokenOwner[tokenID].address != address(0), "This NFT does not exist");

        tokenOwner[tokenID] = newOwner;
        emit TransferNFT(tokenID, msg.sender, newOwner);
    }

    // Function to buy an NFT
    function buyNFT(uint256 tokenID, uint256 etherAmount) public payable {
        require(tokenOwner[tokenID].address != address(0), "This NFT does not exist");
        require(isTokenSold[tokenID] == false, "This NFT is already sold");

        tokenBuyer[tokenID] = msg.sender;
        tokenSalePrice[tokenID] = etherAmount;
        isTokenSold[tokenID] = true;

        emit TransferNFT(tokenID, address(0), msg.sender);
    }

    // Function to get the metadata of an NFT
    function getMetadata(uint256 tokenID) public view returns (string memory) {
        return tokenMetaData[tokenID];
    }

    // Function to get the owner of an NFT
    function getOwner(uint256 tokenID) public view returns (address) {
        return tokenOwner[tokenID];
    }
}
