```java
import android.app.AlertDialog;
import android.content.Context;
import android.content.DialogInterface;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.os.Bundle;
import android.view.View;
import android.widget.ArrayAdapter;
import android.widget.Button;
import android.widget.EditText;
import android.widget.ListView;
import android.widget.Toast;

import androidx.appcompat.app.AppCompatActivity;

import java.util.ArrayList;
import java.util.List;

public class ShopActivity extends AppCompatActivity {
    private ListView listView;
    private Button addButton, modifyButton, deleteButton;
    private EditText itemNameEditText, itemPriceEditText;
    private SQLiteDatabase db;

    private List<String> items = new ArrayList<>();
    private ArrayAdapter<String> adapter;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_shop);

        listView = findViewById(R.id.listView);
        addButton = findViewById(R.id.add_button);
        modifyButton = findViewById(R.id.modify_button);
        deleteButton = findViewById(R.id.delete_button);
        itemNameEditText = findViewById(R.id.item_name_edit_text);
        itemPriceEditText = findViewById(R.id.item_price_edit_text);

        db = openOrCreateDatabase("shopping_cart.db", Context.MODE_PRIVATE, null);
        db.execSQL("CREATE TABLE IF NOT EXISTS items (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, price REAL);");

        adapter = new ArrayAdapter<>(this, R.layout.list_item, R.id.list_item_text, items);
        listView.setAdapter(adapter);
        listView.setOnItemClickListener(new AdapterView.OnItemClickListener() {
            @Override
            public void onItemClick(AdapterView<?> parent, View view, int position, long id) {
                String selectedItem = items.get(position);
                itemPriceEditText.setText(selectedItem.split(":")[1]);
                itemNameEditText.setText(selectedItem.split(":")[0]);
            }
        });

        addButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                String itemName = itemNameEditText.getText().toString();
                double itemPrice = Double.parseDouble(itemPriceEditText.getText().toString());

                if (itemName.isEmpty() || itemPrice == 0) {
                    Toast.makeText(ShopActivity.this, "Please enter item name and price", Toast.LENGTH_SHORT).show();
                    return;
                }

                db.execSQL("INSERT INTO items (name, price) VALUES ('" + itemName + "', " + itemPrice + ");");
                items.add(itemName + ": " + itemPrice);
                adapter.notifyDataSetChanged();
                Toast.makeText(ShopActivity.this, "Item added successfully", Toast.LENGTH_SHORT).show();
            }
        });

        modifyButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                String selectedItem = itemNameEditText.getText().toString();
                double itemPrice = Double.parseDouble(itemPriceEditText.getText().toString());

                if (selectedItem.isEmpty() || itemPrice == 0) {
                    Toast.makeText(ShopActivity.this, "Please select an item to modify", Toast.LENGTH_SHORT).show();
                    return;
                }

                int id = getItemId(selectedItem);
                if (id != -1) {
                    db.execSQL("UPDATE items SET name = '" + selectedItem + "', price = " + itemPrice + " WHERE id = " + id + ";");
                    items.set(id, selectedItem + ": " + itemPrice);
                    adapter.notifyDataSetChanged();
                    Toast.makeText(ShopActivity.this, "Item modified successfully", Toast.LENGTH_SHORT).show();
                } else {
                    Toast.makeText(ShopActivity.this, "Item not found", Toast.LENGTH_SHORT).show();
                }
            }
        });

        deleteButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                String selectedItem = itemNameEditText.getText().toString();

                if (selectedItem.isEmpty()) {
                    Toast.makeText(ShopActivity.this, "Please select an item to delete", Toast.LENGTH_SHORT).show();
                    return;
                }

                int id = getItemId(selectedItem);
                if (id != -1) {
                    db.execSQL("DELETE FROM items WHERE id = " + id + ";");
                    items.remove(id);
                    adapter.notifyDataSetChanged();
                    Toast.makeText(ShopActivity.this, "Item deleted successfully", Toast.LENGTH_SHORT).show();
                } else {
                    Toast.makeText(ShopActivity.this, "Item not found", Toast.LENGTH_SHORT).show();
                }
            }
        });
    }

    private int getItemId(String itemName) {
        Cursor cursor = db.rawQuery("SELECT id FROM items WHERE name = '" + itemName + "';", null);
        if (cursor.moveToFirst()) {
            return cursor.getInt(0);
        }
        cursor.close();
        return -1;
    }
}
```
